(assert (= "1.12.6" (clojure-version)))
(println (pr-str (pr-str (try (pr-str (binding [*math-context* :invalid] (mapv bigdec [1 1N (biginteger 1)]))) (catch Throwable e [:error (.getMessage e)])))))
(println (pr-str (pr-str (try (pr-str (binding [*math-context* :invalid] [(bigdec "1.234") (bigdec 0.1) (bigdec 1.234M)])) (catch Throwable e [:error (.getMessage e)])))))
(println (pr-str (pr-str (try (pr-str (binding [*math-context* :invalid] [(= 1M 1.00M) (== 1M 1) (compare 1M 1) (< 1M 2) (zero? 0.00M) (pos? 1E-1000M) (neg? -1E-1000M)])) (catch Throwable e [:error (.getMessage e)])))))
(println (pr-str (pr-str (try (pr-str (binding [*math-context* :invalid] [(hash 1.00M) (case 1.0M 1.0M :same :different) (rationalize 1.25M) (unchecked-long 1.99M)])) (catch Throwable e [:error (.getMessage e)])))))
(println (pr-str (pr-str (try (try (binding [*math-context* :invalid] (bigdec 1/2)) :accepted (catch Throwable e :rejected)) (catch Throwable e [:error (.getMessage e)])))))
(println (pr-str (pr-str (try (try (binding [*math-context* :invalid] (== 0.5M 1/2)) :accepted (catch Throwable e :rejected)) (catch Throwable e [:error (.getMessage e)])))))
(println (pr-str (pr-str (try (try (binding [*math-context* :invalid] (+ 1M 1M)) :accepted (catch Throwable e :rejected)) (catch Throwable e [:error (.getMessage e)])))))
(println (pr-str (pr-str (try (pr-str (binding [*math-context* :invalid] [(+ 1.234M) (* 1.234M) (decimal? 1M)])) (catch Throwable e [:error (.getMessage e)])))))
